const cleanDesc=t=>[t.room||'Geral',t.dueDate?shortDate(t.dueDate):null,t.status==='done'&&t.completedBy&&assigneesOf(t).length>1?'Concluída por '+owner(t.completedBy).split(' ')[0]:ownersLabel(t)].filter(Boolean);
