async function api(endpoint,method='GET',data,extra){if(demo){await new Promise(r=>setTimeout(r,40));return demoApi(endpoint,method,data);}const opts={method,credentials:'same-origin',headers:{'Accept':'application/json'}};if(method!=='GET'){opts.headers['Content-Type']='application/json';opts.headers['X-Casa-Request']='1';opts.body=JSON.stringify(data||{});if(extra?.opId)opts.headers['X-Op-Id']=extra.opId;}let res;
 try{res=await fetch(endpoint.replace(/^\//,''),opts);offline=false;}catch(e){offline=true;throw Error('Não foi possível contactar o servidor. Verifica a ligação.');}
 const json=await res.json();if(res.status===401&&!/\/api\/(login|access|invites|setup)/.test(endpoint)&&typeof offlineClear==='function')offlineClear();if(res.status===428){renderForcePassword();throw Error(json.error);}if(!res.ok){if(method!=='GET'&&typeof haptic==='function')haptic('error');throw Error(json.error||'Erro ao guardar.');}return json;
}
