function demoApi(p,method,b){if(p==='/api/bootstrap')return {setup:false,user:store.user};{for(const h of demoHandlers){const r=h(p,method,b);if(r!==undefined)return r;}const fx=demoFeatureApi(p,method,b);if(fx!==undefined)return fx;const ff=demoFinanceApi(p,method,b);if(ff!==undefined)return ff;}{const m=p.match(/^\/api\/people\/([^/]+)\/(status|schedule)$/);if(m&&method==='PATCH'){const u=store.people.find(x=>x.id===m[1]);if(!u)throw Error('Pessoa não encontrada.');if(m[2]==='status'){if(u.id===store.user.id)throw Error('Não podes desativar a tua própria conta.');u.active=b.active;let n=0;store.tasks.forEach(t=>{if(!b.active&&t.assignedTo===u.id&&t.status!=='done'){t.assignedTo=null;t.unassignedFrom=u.id;n++;}else if(b.active&&t.unassignedFrom===u.id){if(!t.assignedTo&&t.status!=='done'){t.assignedTo=u.id;n++;}delete t.unassignedFrom;}});persistDemo();return {people:store.people,tasks:n};}else u.accessDays=b.accessDays;persistDemo();return {people:store.people};}}if(p==='/api/me'&&method==='PATCH'){const u=store.people.find(x=>x.id===store.user.id)||store.user;if('name'in b){const n=String(b.name||'').trim();if(n.length<2)throw Error('O nome deve ter pelo menos 2 caracteres.');u.name=n;store.user.name=n;}if('photo'in b)u.photo=b.photo||'';for(const k of ['username','birthDate','email','phone'])if(k in b)u[k]=b[k];persistDemo();return {user:store.user,people:store.people};}if(p==='/api/state'){if(!store.weather&&typeof demoWeather==='function')store.weather=demoWeather();return store;}
 if(p==='/api/logout')return {ok:true};if(p==='/api/settings'&&method==='PATCH'){const {renames,...rest}=b;store.settings={...store.settings,...rest};let moved=0;for(const [f,t] of Object.entries(renames||{}))if(store.settings.rooms.includes(t))for(const x of [...store.tasks,...(store.equipment||[]),...(store.incidents||[])])if(x.room===f){x.room=t;moved++;}persistDemo();return {settings:store.settings,moved};}if(p==='/api/export')return store;if(p==='/api/shopping'&&method==='POST'){const item={...b,id:'si'+Date.now(),purchased:false,createdBy:store.user.id};store.shopping=shopping().concat(item);persistDemo();return {item};}const sm=p.match(/^\/api\/shopping\/([^/]+)$/);if(sm){const it=shopping().find(x=>x.id===sm[1]);if(method==='PATCH'&&it)Object.assign(it,b);if(method==='DELETE')store.shopping=shopping().filter(x=>x.id!==sm[1]);persistDemo();return {item:it};}if(p==='/api/worklogs'&&method==='POST'){const ids=Array.isArray(b.userIds)&&b.userIds.length?b.userIds:[b.userId||store.user.id];const gid=ids.length>1?'g'+Date.now():null;const {userIds,...rest}=b;const entries=ids.map((uid,i)=>({...rest,minutes:Number(b.minutes),id:'wl'+Date.now()+i,userId:uid,actor:store.user.id,createdAt:new Date().toISOString(),...(gid?{groupId:gid}:{})}));store.workLogs=workLogs().concat(entries);persistDemo();return {entry:entries[0],entries};}{const wm=p.match(/^\/api\/worklogs\/([^/?]+)(\?grupo=1)?$/);if(wm){const e=workLogs().find(x=>x.id===wm[1]);if(!e)throw Error('Registo não encontrado.');if(method==='DELETE'){const gone=wm[2]&&e.groupId?workLogs().filter(x=>x.groupId===e.groupId):[e];store.workLogs=workLogs().filter(x=>!gone.includes(x));const rest=e.groupId?workLogs().filter(x=>x.groupId===e.groupId):[];if(rest.length===1)delete rest[0].groupId;persistDemo();return {ok:true};}const {userIds,...rest}=b;const f={...rest,minutes:Number(b.minutes)||e.minutes};if(!Array.isArray(userIds)){Object.assign(e,f);persistDemo();return {entry:e};}const group=e.groupId?workLogs().filter(x=>x.groupId===e.groupId):[e];const gid=userIds.length>1?(e.groupId||'g'+Date.now()):null;const keep=[];for(const x of group){if(userIds.includes(x.userId)){Object.assign(x,f);if(gid)x.groupId=gid;else delete x.groupId;keep.push(x);}else store.workLogs=workLogs().filter(y=>y!==x);}userIds.forEach((uid,i)=>{if(!keep.some(k=>k.userId===uid)){const x={...e,...f,id:'wl'+Date.now()+i,userId:uid,actor:store.user.id,...(gid?{groupId:gid}:{})};store.workLogs=workLogs().concat(x);keep.push(x);}});persistDemo();return {entry:keep[0],entries:keep};}}
 if(p==='/api/tasks'&&method==='POST'){const t={id:'d'+Date.now()+Math.random().toString().slice(2),createdAt:new Date().toISOString(),...b};store.tasks.push(t);persistDemo();return {task:t};}
 const m=p.match(/^\/api\/tasks\/([^/]+)(\/complete)?$/);if(m){let t=tasks().find(x=>x.id===m[1]);if(!t)throw Error('Tarefa não encontrada.');if(m[2]){store.history.push({id:'h'+Date.now(),taskId:t.id,title:t.title,at:new Date().toISOString(),by:store.user.id,kind:t.kind,assignedTo:t.assignedTo});if(t.kind==='routine'&&t.repeat!=='none'){t.status='todo';t.dueDate=nextDemoDate(t.dueDate,t.repeat);t.suggested=false;if(Array.isArray(t.rotation)&&t.rotation.length>1){const i=t.rotation.indexOf(t.assignedTo);t.assignedTo=t.rotation[(i+1)%t.rotation.length];}}else{t.status='done';t.completedBy=store.user.id;}}else if(method==='PATCH'){const {undo,...pb}=b||{};demoRemovedLogs=0;if(t.status==='done'&&pb.status&&pb.status!=='done'){const cut=Date.now()-864e5;const hs=store.history||[];const h=[...hs].reverse().find(x=>x.taskId===t.id&&Date.parse(x.at)>cut);if(h){store.history=hs.filter(x=>x!==h);if(undo){const since=Date.parse(h.at)-6e4;const gone=workLogs().filter(l=>l.taskId===t.id&&Date.parse(l.createdAt||0)>=since);store.workLogs=workLogs().filter(l=>!gone.includes(l));demoRemovedLogs=gone.length;}}}b=pb;Object.assign(t,b);if(Array.isArray(t.coAssignees)){t.coAssignees=t.coAssignees.filter(x=>x&&x!==t.assignedTo);if(!t.coAssignees.length)delete t.coAssignees;}if(t.status!=='done')delete t.completedBy;else if(!t.completedBy)t.completedBy=store.user.id;}else if(method==='DELETE'){store.tasks=tasks().filter(x=>x.id!==t.id);}persistDemo();return {task:t,removedLogs:method==='PATCH'?demoRemovedLogs:0};}
 if(p==='/api/people'&&method==='POST'){store.people.push({id:'u'+Date.now(),name:b.name,username:b.username,role:b.role||'resident'});persistDemo();return {people:store.people};}{const pe=p.match(/^\/api\/people\/([^/]+)$/);if(pe&&method==='PATCH'){const u=store.people.find(x=>x.id===pe[1]);if(u){for(const k of ['name','username','birthDate','email','phone'])if(k in b)u[k]=b[k];if('photo'in b)u.photo=b.photo||'';if(u.id===store.user.id)store.user.name=u.name;}persistDemo();return {people:store.people};}}const roleMatch=p.match(/^\/api\/people\/([^/]+)\/role$/);if(roleMatch&&method==='PATCH'){const u=store.people.find(x=>x.id===roleMatch[1]);if(u)u.role=b.role;persistDemo();return {people:store.people};}
 return {ok:true};}
function nextDemoDate(iso,repeat){let d=iso?new Date(iso+'T12:00:00Z'):new Date();const step=()=>{if(repeat==='monthly')d.setUTCMonth(d.getUTCMonth()+1);else if(repeat==='quarterly')d.setUTCMonth(d.getUTCMonth()+3);else if(repeat==='yearly')d.setUTCFullYear(d.getUTCFullYear()+1);else d.setUTCDate(d.getUTCDate()+({daily:1,weekly:7,biweekly:14}[repeat]||7));};step();while(d<new Date())step();return d.toISOString().slice(0,10);}
