 {const acc=new URLSearchParams(location.search).get('acesso');if(acc&&!demo){await new Promise(r=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',r,{once:true}):r());renderAccess(acc);return;}}
 {const inv=new URLSearchParams(location.search).get('convite');if(inv&&!demo){await new Promise(r=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',r,{once:true}):r());renderInvite(inv);return;}}
 const fromCache=typeof instantBoot==='function'&&instantBoot();
 try{let b=await api('/api/bootstrap');setup=b.setup;if(setup){offlineClear();renderAuth('setup');return;}if(!b.user){offlineClear();renderAuth('login');return;}if(fromCache&&store.user?.id!==b.user.id){offlineClear();store={tasks:[],people:[],history:[],user:null};}if(b.user.mustChangePassword){store.user=b.user;renderForcePassword();return;}const y=fromCache?window.scrollY:0;await load();offline=false;render();if(y)window.scrollTo(0,y);}catch(e){offline=true;if(fromCache)render();else if(!offlineBoot())renderAuth('login',e.message);}finally{if(fromCache)loadEnd();}
