function renderForcePassword(temp=''){
 const aside=`<section class="auth-aside"><div class="brand brand-primary"><img class="brand-primary-logo" src="logo-primary-light.svg" alt="Daily Casa" /></div><div><h1>Bem-vindo à casa.<br/><em>Só falta um passo.</em></h1><p>A tua conta foi criada com uma palavra-passe temporária. Escolhe agora uma só tua.</p></div><small>O teu espaço, os teus dados, o teu ritmo.</small></section>`;
 app.innerHTML=`<div class="auth-layout">${aside}<section class="auth-form"><div class="auth-inner"><img class="auth-mobile-logo" src="logo-primary-dark.svg" alt="Daily Casa" /><h2>Define a tua palavra-passe.</h2><p>Por segurança, a palavra-passe que te deram só serve para esta primeira entrada.</p><form id="force-form">${temp?`<input type="hidden" name="currentPassword" value="${esc(temp)}"/>`:`<div class="field"><label for="force-current">Palavra-passe temporária</label><input id="force-current" type="password" name="currentPassword" autocomplete="current-password" required/></div>`}<div class="field"><label for="force-new">Nova palavra-passe</label><input id="force-new" type="password" name="password" autocomplete="new-password" minlength="10" required placeholder="Mínimo de 10 caracteres"/></div><div class="field"><label for="force-confirm">Repetir a nova palavra-passe</label><input id="force-confirm" type="password" name="confirm" autocomplete="new-password" minlength="10" required/></div><div class="auth-error" id="auth-error" role="alert"></div><button class="button primary auth-submit" type="submit">Guardar e entrar ${ico('chevron')}</button><button class="button ghost-link" type="button" data-action="logout">Terminar sessão</button></form></div></section></div>`;
 const f=$('#force-form');f.addEventListener('submit',async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));if(v.password!==v.confirm){$('#auth-error').textContent='As novas palavras-passe não coincidem.';return;}const btn=f.querySelector('[type=submit]');btn.disabled=true;
  try{await api(`/api/people/${store.user.id}/password`,'POST',{currentPassword:v.currentPassword,password:v.password});await load();render();toast('Palavra-passe definida. Bem-vindo!');}catch(err){$('#auth-error').textContent=err.message;}finally{btn.disabled=false;}});
}
function renderAuth(mode,err=''){const isSetup=mode==='setup';document.querySelector('meta[name=theme-color]')?.setAttribute('content','#17261E');app.innerHTML=`<div class="auth-layout"><section class="auth-aside"><div class="brand brand-primary"><img class="brand-primary-logo" src="logo-primary-light.svg" alt="Daily Casa" /></div><div><h1>A casa em dia,<br/><em>todos os dias.</em></h1><p>Um espaço comum para organizar pendências, dividir tarefas e celebrar o que já está feito.</p></div><small>O teu espaço, os teus dados, o teu ritmo.</small></section><section class="auth-form"><div class="auth-inner"><img class="auth-mobile-logo" src="logo-primary-dark.svg" alt="Daily Casa" /><div class="eyebrow">DAILY CASA · ${isSetup?'PRIMEIRO ACESSO':'BEM-VINDO DE VOLTA'}</div><h2>${isSetup?'Vamos preparar a tua casa.':'Entrar na tua casa.'}</h2><p>${isSetup?'Cria a primeira conta, que poderá convidar as restantes pessoas da casa.':'Inicia sessão para veres e atualizares as tarefas partilhadas.'}</p><form id="auth-form">${isSetup?`<div class="field"><label>O teu nome</label><input autocomplete="name" name="name" required minlength="2" placeholder="Como queres ser identificado"/></div>`:''}<div class="field"><label for="auth-email">Email</label><input id="auth-email" type="${isSetup?'email':'text'}" autocomplete="username" name="email" required inputmode="email" autocapitalize="none" spellcheck="false" placeholder="nome@exemplo.pt"/></div><div class="field"><label for="auth-password">Palavra-passe</label><input id="auth-password" type="password" autocomplete="${isSetup?'new-password':'current-password'}" name="password" minlength="${isSetup?10:1}" required placeholder="${isSetup?'Mínimo de 10 caracteres':'A tua palavra-passe'}"/></div>${isSetup?'':`<label class="remember-row" for="auth-remember"><input id="auth-remember" type="checkbox" name="remember" checked/><span class="remember-box" aria-hidden="true">${ico('check')}</span><span>Manter sessão iniciada</span></label>`}<button class="button primary auth-submit" type="submit">${ico('login')}<span>${isSetup?'Criar casa e entrar':'Login'}</span></button><div class="auth-message" id="auth-error">${esc(err)}</div>${isSetup?'':'<button type="button" class="auth-link" data-action="forgot-open">Esqueci-me da palavra-passe</button>'}</form></div></section></div>`;
 const f=$('#auth-form');f.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));data.remember=isSetup||!!f.querySelector('[name=remember]')?.checked;const submit=f.querySelector('button[type=submit]');submit.disabled=true;try{const r=await api(isSetup?'/api/setup':'/api/login','POST',data);if(r.user?.mustChangePassword){store.user=r.user;renderForcePassword(data.password);return;}
  // Recarregar a página depois de entrar: é a navegação a seguir ao formulário que leva o iPhone (e os browsers) a propor guardar a palavra-passe.
  location.replace(location.pathname+location.search);return;}catch(e){$('#auth-error').textContent=e.message;}finally{submit.disabled=false;}});
}
/* Navegação: quatro destinos (Hoje · Tarefas · Compras · Casa) e o «+» ao centro.
   O que se usa menos vive dentro de «Casa»; Rotinas, Calendário e Divisões são vistas de «Tarefas». */
const NAV_MAIN=[['today','Hoje','today'],['tasks','Tarefas','list'],['shopping','Compras','cart'],['house','Casa','home']];
// Páginas dentro de «Casa» (a ordem é a do índice). canSee decide se a pessoa a vê.
const HOUSE_PAGES=[
 ['calendar','Calendário','calendar','Mês, feriados e aniversários',()=>true],
 ['incidents','Ocorrências','alert','Algo partiu, avariou ou falta',()=>true],
 ['balance','Equilíbrio da casa','scale','Esforço de cada pessoa esta semana',()=>store.user?.role!=='collaborator'],
 ['equipment','Equipamentos','tool','Manuais, garantias e revisões',()=>store.user?.role!=='collaborator'],
 ['finance','Finanças','wallet','Despesas, fixas e património',()=>['admin','manager'].includes(store.user?.role)],
 ['people','Pessoas','users','Contas, perfis e permissões',()=>true],
 ['worklogs','Registo de horas','clock','Trabalhos e tempo de cada pessoa',()=>true],
 ['settings','Definições','sliders-horizontal','A casa, notificações e dados',()=>true]];
const TASK_VIEWS=[['list','Lista'],['routines','Rotinas'],['calendar','Calendário'],['rooms','Divisões']];
let taskView='list',quickFilter='mine';
const actionHandlers=[];const demoHandlers=[]; // demonstração: (path,method,body)=>resposta ou undefined
const modalRenderers={}; // janelas que sobrevivem a um novo desenho da página: type → (holder)=>void
 // módulos acrescentam aqui as suas ações: async (name,el)=>true se trataram a ação
// Ligações antigas (notificações, atalhos) continuam a funcionar.
function normalizePage(){if(page==='dashboard')page='today';if(page==='routines'){page='tasks';taskView='routines';}if(page==='calendar'){page='tasks';taskView='calendar';}if(page==='rooms'){page='tasks';taskView='rooms';}}
const sectionOf=p=>NAV_MAIN.some(x=>x[0]===p)?p:p==='notifications'?'today':'house';
const pageTitle=p=>(NAV_MAIN.find(x=>x[0]===p)||HOUSE_PAGES.find(x=>x[0]===p)||{notifications:[0,'Notificações']}[p]||[])[1]||'';
function go(target,opts={}){quickCreateOpen=false;moreOpen=false;notifOpen=false;page=target;normalizePage();if(opts.view)taskView=opts.view;modal=null;if(!opts.keepFilters){query='';personFilter='all';roomFilter='all';priorityFilter='all';statusFilter='all';quickFilter='mine';}render();window.scrollTo(0,0);}
// Localização no topo (computador): só mostra o caminho quando há um nível acima para onde voltar.
function crumbs(){const sep='<span class="crumb-sep" aria-hidden="true">/</span>';const link=(pg,l,extra='')=>`<button type="button" class="crumb-link" data-action="${pg==='settings'?'settings-open':'nav'}" data-page="${pg}" ${extra}>${esc(l)}</button>`;
 const parts=[];if(sectionOf(page)==='house'&&page!=='house')parts.push(link('house','Casa'));
 const sec=page==='settings'&&typeof settingsSection!=='undefined'&&settingsSection?SETTINGS_SECTIONS.find(x=>x[0]===settingsSection):null;
 if(sec){parts.push(link('settings','Definições','data-section=""'));parts.push(`<b aria-current="page">${esc(sec[1])}</b>`);}else parts.push(`<b aria-current="page">${esc(pageTitle(page))}</b>`);
 return parts.join(sep);}
function tabNav(){
 const sec=sectionOf(page);
 const tab=([id,label,icon])=>{const on=sec===id;return `<button class="tab-item ${on?'active':''}" data-action="nav" data-page="${id}" ${on?'aria-current="page"':''}>${ico(icon)}<span>${label}</span></button>`;};
 return `<nav class="mobile-nav tab-nav" aria-label="Navegação principal">${tab(NAV_MAIN[0])}${tab(NAV_MAIN[1])}<button type="button" class="tab-add ${quickCreateOpen?'is-open':''}" data-action="quick-toggle" aria-haspopup="menu" aria-expanded="${quickCreateOpen}" aria-label="${quickCreateOpen?'Fechar menu de criação rápida':'Criar novo'}">${ico('plus')}</button>${tab(NAV_MAIN[2])}${tab(NAV_MAIN[3])}</nav>`;
}
function sidebarNav(){
 const sec=sectionOf(page);const open=tasks().filter(t=>t.status!=='done'&&t.dueDate&&t.dueDate<=today()).length;
 const main=NAV_MAIN.map(([id,label,icon])=>`<button class="nav-link ${sec===id&&(id!=='house'||page==='house')?'active':''}" data-action="nav" data-page="${id}" ${sec===id?'aria-current="page"':''}>${ico(icon)}<span>${label}</span>${id==='today'&&open?`<span class="count">${open}</span>`:''}</button>`).join('');
 const sub=HOUSE_PAGES.filter(x=>x[0]!=='calendar'&&x[4]()).map(([id,label,icon])=>`<button class="nav-link nav-sub ${page===id?'active':''}" data-action="nav" data-page="${id}">${ico(icon)}<span>${label}</span></button>`).join('');
 return `<div class="nav-label">ESPAÇO DA CASA</div>${main}<div class="nav-label nav-label-sub">NA CASA</div>${sub}`;
}
const quickOptions=[['task','Nova tarefa','list'],['routine','Nova rotina','repeat'],['shopping','Produto de compras','cart'],['worklog','Registo de horas','clock'],['incident','Reportar ocorrência','alert'],['equipment','Equipamento','tool'],['finance','Despesa da casa','wallet']];
function quickCreateMenu(){
 if(!quickCreateOpen)return '';
 const items=quickOptions.filter(i=>(i[0]!=='finance'&&i[0]!=='equipment')||['admin','manager'].includes(store.user?.role));
 const menuItems=items.map(i=>'<button type="button" role="menuitem" data-action="quick-new" data-kind="'+i[0]+'">'+ico(i[2])+'<span>'+i[1]+'</span>'+ico('chevron')+'</button>').join('');
 return '<button class="quick-create-dismiss" type="button" data-action="quick-close" tabindex="-1" aria-label="Fechar menu"></button><div class="quick-create-menu" id="quick-create-menu" role="menu" aria-label="Criar novo"><span class="quick-create-heading">CRIAR NOVO</span>'+menuItems+'</div>';
}
let lastRendered=null;
function render(){if(!store.user){renderAuth('login');return;}normalizePage();const current=store.user;if(!HOUSE_PAGES.every(x=>x[0]!==page||x[4]()))page='house';formDirty=false;const pageChanged=lastRendered!==page+'|'+taskView;const keepY=!pageChanged?window.scrollY:0;lastRendered=page+'|'+taskView;
 app.innerHTML=`<div class="layout"><aside class="sidebar"><button type="button" class="brand brand-primary brand-home" data-action="nav" data-page="today" aria-label="Daily Casa — ir para Hoje"><img class="brand-primary-logo" src="logo-primary-light.svg" alt="" /></button>${sidebarNav()}<div class="sidebar-bottom"><button type="button" class="profile-pill" data-action="profile-open" aria-label="O teu perfil">${avatarHtml(me(),'gold')}<span><div class="profile-name">${esc(current.name)}</div><div class="profile-role">${({admin:'Administrador',manager:'Gestor da casa',resident:'Morador',collaborator:'Colaborador'}[current.role]||'Morador')}</div></span></button></div></aside><main class="main"><header class="topline"><nav class="crumb" aria-label="Localização">${crumbs()}</nav><div class="top-actions"><button class="icon-btn" data-action="refresh" aria-label="Atualizar">${ico('refresh')}</button>${searchButton()}${bellButton()}<button type="button" class="profile-btn" data-action="profile-open" aria-label="O teu perfil">${avatarHtml(me(),'user-circle')}</button></div></header><header class="mobile-header"><button type="button" class="brand brand-primary mobile-primary brand-home" data-action="nav" data-page="today" aria-label="Daily Casa — ir para Hoje"><img class="brand-primary-logo" src="logo-primary-dark.svg" alt="" /></button><span class="mobile-head-actions">${searchButton()}${bellButton()}<button type="button" class="profile-btn" data-action="profile-open" aria-label="O teu perfil">${avatarHtml(me())}</button></span></header>${demo?`<div class="demo-banner"><span><strong>Modo demonstração.</strong> As alterações ficam apenas neste dispositivo. A versão com servidor sincroniza entre pessoas.</span><button data-action="reset-demo">Repor</button></div>`:''}${offline||pendingCount()?offlineBanner():''}<div id="content">${houseBack()}${content()}</div></main>${tabNav()}<button class="floating-add ${quickCreateOpen?'is-open':''}" type="button" data-action="quick-toggle" aria-label="${quickCreateOpen?'Fechar menu de criação rápida':'Criar novo'}" aria-haspopup="menu" aria-expanded="${quickCreateOpen}" aria-controls="quick-create-menu">${ico('plus')}</button>${quickCreateMenu()}${notifPanel()}</div><div id="modal-holder"></div>`;
 if(pageChanged)document.getElementById('content')?.classList.add('page-enter');slideIndicators();{const at=document.querySelector('.fin-tabs button.active');const box=at?.parentElement;if(at&&box&&box.scrollWidth>box.clientWidth)box.scrollLeft=Math.max(0,at.offsetLeft-(box.clientWidth-at.offsetWidth)/2);}if(keepY)window.scrollTo(0,keepY);if(modal)renderModal();associateLabels(document);const swipeNav=document.querySelector('.swipe-nav');const currentTab=swipeNav?.querySelector('[aria-current=page]');if(swipeNav&&currentTab){swipeNav.scrollLeft=Math.max(0,currentTab.offsetLeft-swipeNav.offsetLeft-(swipeNav.clientWidth-currentTab.offsetWidth)/2);}const sf=$('#shopping-form');if(sf)sf.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/shopping','POST',Object.fromEntries(new FormData(sf)));await reload();toast('Produto adicionado.');}catch(err){toast(err.message);}});const wf=$('#worklog-form');if(wf)wf.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/worklogs','POST',Object.fromEntries(new FormData(wf)));await reload();toast('Trabalho registado.');}catch(err){toast(err.message);}});const cf=$('#config-form');if(cf)cf.addEventListener('submit',async e=>{e.preventDefault();const read=k=>[...cf.querySelectorAll('[data-config-item="'+k+'"]')].map(x=>x.value.trim()).filter(Boolean);const rooms=read('rooms'),categories=read('categories'),floors=read('floors');const roomFloors={};cf.querySelectorAll('[data-list="rooms"] .manager-item').forEach(row=>{const n=row.querySelector('[data-config-item]')?.value.trim();const f=row.querySelector('[data-config-floor]')?.value;if(n&&f&&floors.includes(f))roomFloors[n]=f;});for(const arr of [rooms,categories,floors]){if(arr.length>100||new Set(arr.map(x=>x.toLocaleLowerCase('pt-PT'))).size!==arr.length)return toast('Remove os nomes repetidos ou inválidos.');}const renames={};cf.querySelectorAll('[data-config-item="rooms"][data-orig]').forEach(i=>{const o=i.dataset.orig,n=i.value.trim();if(o&&n&&o!==n&&!rooms.includes(o))renames[o]=n;});cf.querySelectorAll('[data-orphan]').forEach(sel=>{if(sel.value)renames[sel.dataset.orphan]=sel.value;});try{const r=await api('/api/settings','PATCH',{rooms,categories,floors,roomFloors,renames});await reload();toast(r.moved?`Pisos e divisões guardados. ${plural(r.moved,'item mudou','itens mudaram')} de divisão.`:'Pisos, divisões e categorias guardados.');}catch(err){toast(err.message);}});
}
function content(){switch(page){case 'today':return todayPage();case 'tasks':return tasksPage();case 'house':return housePage();case 'balance':return balancePage();case 'equipment':return equipmentPage();case 'incidents':return incidentsPage();case 'people':return peoplePage();case 'shopping':return shoppingPage();case 'worklogs':return worklogsPage();case 'finance':return financePage();case 'settings':return settingsPage();case 'notifications':return notificationsPage();default:return todayPage();}}
// 3.12: no telemóvel, as páginas dentro de «Casa» têm um «voltar» por cima do título (no computador existe o caminho no topo).
const houseBack=()=>page!=='house'&&HOUSE_PAGES.some(x=>x[0]===page)&&!(page==='settings'&&typeof settingsSection!=='undefined'&&settingsSection)?`<button type="button" class="back-link back-house" data-action="nav" data-page="house">${ico('back')} Casa</button>`:'';
const head=(title,subtitle,add=true)=>`<div class="header-row"><div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${add?`<button class="button primary" data-action="add">${ico('plus-square')} Nova tarefa</button>`:''}</div>`;
function taskRow(t,large=false){let done=t.status==='done';const editable=canEditVisible(t),completable=canCompleteVisible(t);return `<div class="task-row ${large?'large':''}" data-task="${esc(t.id)}"><button class="task-check ${done?'checked':''}" aria-label="${done?'Reabrir':'Concluir'} ${esc(t.title)}" data-action="complete" data-id="${esc(t.id)}" ${!completable?'disabled':''}>${done?ico('check'):''}</button><button class="task-detail" data-action="edit" data-id="${esc(t.id)}"><div class="task-title ${done?'done':''}">${esc(t.title)}</div><div class="task-meta">${t.kind==='routine'?'<span class="kind-tag">'+ico('repeat')+esc(repeatLabels[t.repeat]||'Rotina')+'</span>':''}${t.equipmentId?'<span class="kind-tag">'+ico('tool')+'Revisão</span>':''}${t.assignRequest?'<span class="kind-tag pending">'+ico('clock')+'Pedido: '+esc(owner(t.assignRequest.to).split(' ')[0])+'</span>':''}${t.estimatedMinutes!=null?esc(t.estimatedMinutes)+' min · ':''}${(t.subtasks||[]).length?(t.subtasks.filter(s=>s.done).length+'/'+t.subtasks.length+' passos · '):''}${cleanDesc(t).map(x=>esc(x)).join('<span class="dot"></span>')}${t.suggested?'<span class="dot"></span>Exemplo':''}</div></button>${isOverdue(t)?'<span class="status overdue">Atrasada</span>':''}${t.status!=='todo'?`<span class="status ${esc(t.status)}">${esc(labels[t.status])}</span>`:''}${t.priority==='P1'||t.priority==='P2'?`<span class="priority-word ${esc(t.priority)}">${esc(PRIORITIES[t.priority])}</span>`:''}<span class="small-avatar ${t.assignedTo?'':'none'}" title="${esc(owner(t.assignedTo))}">${t.assignedTo?esc(initials(owner(t.assignedTo))):'—'}</span></div>`;}
function empty(icon,title,text){return `<div class="empty"><div class="empty-icon">${ico(icon)}</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;}
function getFiltered(kind){let a=tasks().filter(t=>t.kind===kind);if(kind==='project'&&tab==='active')a=a.filter(x=>x.status!=='done');if(kind==='project'&&tab==='done')a=a.filter(x=>x.status==='done');if(statusFilter!=='all')a=a.filter(x=>x.status===statusFilter);if(personFilter!=='all')a=a.filter(x=>personFilter==='none'?!x.assignedTo:isAssignee(x,personFilter));if(roomFilter!=='all')a=a.filter(x=>x.room===roomFilter);if(priorityFilter!=='all')a=a.filter(x=>x.priority===priorityFilter);if(query)a=a.filter(x=>(x.title+' '+x.notes+' '+x.room).toLowerCase().includes(query.toLowerCase()));return a.sort((a,b)=>{const rank={P1:0,P2:1,P3:2,P4:3};return rank[a.priority]-rank[b.priority]||Number(!!a.dueDate)-Number(!!b.dueDate)||a.title.localeCompare(b.title,'pt-PT');});}
function option(value,text,selected){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(text)}</option>`;}
function filtersHtml(kind){const rooms=[...new Set(tasks().filter(t=>t.kind===kind).map(t=>t.room).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-PT'));
 return `<div class="filters"><label class="search">${ico('search')}<input name="search" type="search" placeholder="Pesquisar por tarefa ou divisão..." value="${esc(query)}" aria-label="Pesquisar tarefas" /></label><select class="select-control" name="person-filter" aria-label="Filtrar responsável">${option('all','Todos os responsáveis',personFilter)}${option('none','Sem responsável',personFilter)}${people().map(p=>option(p.id,p.name,personFilter)).join('')}</select><select class="select-control" name="room-filter" aria-label="Filtrar divisão">${option('all','Todas as divisões',roomFilter)}${roomOptions(rooms,roomFilter)}</select><select class="select-control" name="priority-filter" aria-label="Filtrar prioridade">${option('all','Todas as prioridades',priorityFilter)}${['P1','P2','P3','P4'].map(p=>option(p,PRIORITIES[p],priorityFilter)).join('')}</select></div>`;}
function routinesPage(){const rs=getFiltered('routine').slice().sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));return `<div class="routine-overview"><strong>Próximas rotinas</strong><span>${rs.filter(t=>t.dueDate&&t.dueDate<=today()).length} para hoje ou atrasadas · ${rs.length} no total</span></div><div class="filters-summary"><button class="button" data-action="filter-toggle" aria-expanded="${taskFiltersOpen}">${ico('filter')} ${taskFiltersOpen?'Ocultar filtros':'Filtros'}</button><button class="button" data-action="clear-filters">Limpar filtros</button></div><div class="${taskFiltersOpen?'':'filters-collapsed'}">${filtersHtml('routine')}</div><div class="routine-grid">${rs.map(t=>`<article class="routine-card"><div class="routine-head"><div class="icon">${ico('broom')}</div><span class="tag">${esc(repeatLabels[t.repeat]||'Pontual')}</span></div><div><div class="routine-title">${esc(t.title)}</div><div class="routine-caption">${esc(t.room)} · ${esc(owner(t.assignedTo))}${t.dueDate?' · '+esc(shortDate(t.dueDate)):''}</div>${t.suggested?'<div class="routine-caption" style="color:#a2854e;margin-top:5px">Rotina de exemplo — personaliza-a</div>':''}${rotationLine(t)}</div><div class="routine-footer"><button class="button small" data-action="edit" data-id="${esc(t.id)}">${ico('edit')} Editar</button><button class="button small primary" data-action="complete" data-id="${esc(t.id)}">${ico('check-square')} Feita</button></div></article>`).join('')}</div>${rs.length?'':`<div class="panel">${empty('calendar','Sem rotinas','Adiciona uma rotina para repartir as tarefas habituais.')}</div>`}<div class="info-note">As rotinas com repetição voltam automaticamente à lista depois de marcadas como feitas, com nova data. As que não têm data definida recebem uma data para a próxima ocorrência após a primeira conclusão.</div>`;}
function shoppingPage(){const all=shopping().slice().sort((a,b)=>Number(a.purchased)-Number(b.purchased));const items=shoppingView==='all'?all:all.filter(x=>!x.purchased);const grouped=items.reduce((out,i)=>{(out[i.category||'Geral']??=[]).push(i);return out;},{});return `<div class="header-row"><div><h1 class="page-title">Compras</h1><p class="page-subtitle">O que falta comprar, em equipa.</p></div>${all.some(x=>!x.purchased)?`<button type="button" class="button store-btn" data-action="store-open">${ico('store')} Modo loja</button>`:''}</div><div class="shopping-switch"><button data-action="shopping-view" data-view="open" class="${shoppingView==='open'?'active':''}">Por comprar · ${all.filter(x=>!x.purchased).length}</button><button data-action="shopping-view" data-view="all" class="${shoppingView==='all'?'active':''}">Todas · ${all.length}</button></div>${shoppingQuickHtml()}<div class="panel table-panel"><div class="task-list">${items.length?Object.entries(grouped).map(([category,entries])=>`<section class="shopping-category"><h3>${esc(category)}</h3>${entries.map(i=>`<div class="shopping-line"><input type="checkbox" class="shop-check" data-action="shopping-toggle" data-id="${esc(i.id)}" ${i.purchased?'checked':''} aria-label="${i.purchased?'Voltar a pôr':'Marcar'} ${esc(i.title)} ${i.purchased?'na lista':'como comprado'}"/><button type="button" class="shop-name" data-action="shop-edit" data-id="${esc(i.id)}" aria-label="Editar ${esc(i.title)}"><span class="${i.purchased?'done':''}">${esc(i.title)}</span>${i.notes?`<small>${esc(i.notes)}</small>`:''}</button><button type="button" class="shopping-qty" data-action="shop-edit" data-id="${esc(i.id)}" aria-label="Quantidade de ${esc(i.title)}: ${esc(CasaUnits.format(i.quantity,i.unit))}. Editar">${esc(CasaUnits.format(i.quantity,i.unit))}</button></div>`).join('')}</section>`).join(''):empty('list','Lista vazia','Adiciona o primeiro produto.')}</div></div>`;}
const fmtMinutes=m=>{const h=Math.floor(m/60),r=m%60;return h?`${h}h${r?' '+String(r).padStart(2,'0')+'m':''}`:`${r}m`;};
function hoursSummary(){const logs=workLogs().filter(x=>(x.date||'').startsWith(worklogMonth));const by={};for(const x of logs){const k=x.userId||'?';(by[k]??={n:0,m:0,days:new Set()});by[k].n++;by[k].m+=Number(x.minutes||0);by[k].days.add(x.date);}
 const rows=Object.entries(by).sort((a,b)=>b[1].m-a[1].m);const total=rows.reduce((n,[,v])=>n+v.m,0);
 const months=[...new Set([worklogMonth,today().slice(0,7),...workLogs().map(x=>(x.date||'').slice(0,7)).filter(Boolean)])].sort().reverse();
 return `<section class="hours-summary" aria-labelledby="hours-title"><div class="hours-head"><div><h3 id="hours-title">Horas por pessoa</h3><p>${canManage()?'Resumo do mês para acompanhar o trabalho de cada pessoa, incluindo colaboradores.':'O teu resumo do mês.'}</p></div><select class="select-control" id="worklog-month" aria-label="Mês do resumo">${months.map(m=>option(m,monthLong(m),worklogMonth)).join('')}</select></div>
 ${rows.length?`<div class="perm-wrap"><table class="hours-table"><thead><tr><th scope="col">Pessoa</th><th scope="col">Dias</th><th scope="col">Registos</th><th scope="col">Tempo</th></tr></thead><tbody>${rows.map(([id,v])=>{const pp=people().find(x=>x.id===id);return `<tr><th scope="row"><span class="hours-person">${avatarHtml(pp||{name:'?'},'mini')}${esc(owner(id))}${pp?.role==='collaborator'?' <span class="person-badge days">Colaborador</span>':''}</span></th><td>${v.days.size}</td><td>${v.n}</td><td><b>${fmtMinutes(v.m)}</b></td></tr>`;}).join('')}</tbody><tfoot><tr><th scope="row">Total</th><td></td><td>${rows.reduce((n,[,v])=>n+v.n,0)}</td><td><b>${fmtMinutes(total)}</b></td></tr></tfoot></table></div>`:`<p class="muted">Sem registos em ${esc(MONTHS_FULL[Number(worklogMonth.slice(5,7))-1]||'')} de ${esc(worklogMonth.slice(0,4))}.</p>`}</section>`;}
// 3.13: worklogsPage passou para features.js (abre pelo histórico; registar numa janela).
