// Puxar para atualizar (ecrãs táteis): puxar no topo da página → largar → atualizar.
(function pullToRefresh(){
 if(!('ontouchstart' in window))return;
 const THRESHOLD=72,MAX=112;let startY=null,dist=0,busy=false;
 const el=document.createElement('div');el.className='ptr';el.setAttribute('role','status');el.setAttribute('aria-live','polite');
 el.innerHTML=ico('refresh','ptr-icon')+'<span class="ptr-text">Puxar para atualizar</span>';document.body.appendChild(el);
 const text=el.querySelector('.ptr-text'),icon=el.querySelector('.ptr-icon');
 const show=(d)=>{el.style.transform=`translate(-50%,${d-56}px)`;el.style.opacity=String(Math.min(1,d/40));icon.style.transform=`rotate(${d*3}deg)`;};
 const hide=()=>{el.classList.add('ptr-settle');el.style.transform='translate(-50%,-56px)';el.style.opacity='0';setTimeout(()=>{el.classList.remove('ptr-settle','ptr-loading');text.textContent='Puxar para atualizar';},260);};
 const blocked=t=>modal||quickCreateOpen||!store.user||t.closest('.tab-nav,.more-sheet,input,textarea,select,.modal,.quick-create-menu');
 window.addEventListener('touchstart',e=>{if(busy||window.scrollY>0||e.touches.length!==1||blocked(e.target)){startY=null;return;}startY=e.touches[0].clientY;dist=0;},{passive:true});
 window.addEventListener('touchmove',e=>{if(startY===null||busy)return;const dy=e.touches[0].clientY-startY;if(dy<=0||window.scrollY>0){dist=0;show(0);return;}
  dist=Math.min(MAX,dy*0.5);if(e.cancelable)e.preventDefault();show(dist);text.textContent=dist>=THRESHOLD?'Largar para atualizar':'Puxar para atualizar';el.classList.toggle('ptr-ready',dist>=THRESHOLD);},{passive:false});
 window.addEventListener('touchend',async()=>{if(startY===null||busy)return;startY=null;el.classList.remove('ptr-ready');
  if(dist<THRESHOLD){hide();return;}
  busy=true;el.classList.add('ptr-settle','ptr-loading');show(THRESHOLD);text.textContent='A atualizar…';
  const t0=Date.now();await reload();await new Promise(r=>setTimeout(r,Math.max(0,600-(Date.now()-t0))));
  text.textContent=offline?'Sem ligação ao servidor':'Atualizado';el.classList.remove('ptr-loading');
  setTimeout(()=>{hide();busy=false;},700);});
 window.addEventListener('touchcancel',()=>{if(!busy){startY=null;hide();}});
})();
document.addEventListener('change',async e=>{const sel=e.target;if(!sel.matches?.('.role-choice'))return;const pn=people().find(x=>x.id===sel.dataset.person);if(!await confirmDialog({title:'Mudar o perfil?',message:`${pn?.name||'Esta pessoa'} passa a ${ROLE_LABELS[sel.value]}. A sessão dela termina e terá de voltar a entrar.`,confirmLabel:'Mudar perfil'}))return render();try{await api('/api/people/'+sel.dataset.person+'/role','PATCH',{role:sel.value});await reload();toast('Perfil atualizado.');}catch(e){toast(e.message);}});
/* 3.12 — Movimento com significado: concluir, separadores que deslizam. Sem efeito com «reduzir movimento». */
const calmMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
async function completeAnim(btn){const row=btn.closest('.task-row,.plan-item');if(!row||calmMotion())return;
 btn.classList.add('checked','pop');btn.innerHTML=ico('check');row.style.height=row.offsetHeight+'px';void row.offsetHeight;row.classList.add('completing');
 await new Promise(r=>setTimeout(r,560));}
const indPos={};
function slideIndicators(){document.querySelectorAll('.view-tabs,.seg-control,.fin-tabs,.shopping-switch').forEach(box=>{
 const on=box.querySelector('button.active,button[aria-checked="true"],[role=tab][aria-selected="true"]');if(!on){box.classList.remove('has-ind');return;}box.classList.add('has-ind');
 const key=page+'|'+(box.getAttribute('aria-label')||box.className);const next={x:on.offsetLeft,y:on.offsetTop,w:on.offsetWidth,h:on.offsetHeight};
 const set=v=>{box.style.setProperty('--ix',v.x+'px');box.style.setProperty('--iy',v.y+'px');box.style.setProperty('--iw',v.w+'px');box.style.setProperty('--ih',v.h+'px');};
 const prev=indPos[key];indPos[key]=next;
 if(prev&&!calmMotion()&&(prev.x!==next.x||prev.w!==next.w)){box.classList.add('ind-still');set(prev);void box.offsetWidth;box.classList.remove('ind-still');requestAnimationFrame(()=>set(next));}else set(next);});}
window.addEventListener('resize',()=>{clearTimeout(slideIndicators.t);slideIndicators.t=setTimeout(slideIndicators,120);});
/* 3.14 — Compra marcada: o visto, o nome riscado e a linha a recolher. Grupos das tarefas abrem e fecham a deslizar. */
async function shopAnim(box){const row=box.closest('.shopping-line');if(!row||calmMotion())return;box.checked=true;box.classList.add('pop');row.style.height=row.offsetHeight+'px';void row.offsetHeight;row.classList.add('buying');await new Promise(r=>setTimeout(r,620));}
document.addEventListener('click',e=>{const sum=e.target.closest?.('details.task-when>summary');if(!sum||calmMotion())return;const d=sum.parentElement;const body=d.querySelector('.task-group');if(!body||d.dataset.anim)return;e.preventDefault();d.dataset.anim='1';
 const done=()=>{delete d.dataset.anim;body.style.overflow='';};
 if(!d.open){d.open=true;const h=body.offsetHeight;body.style.overflow='hidden';body.animate([{height:'0px',opacity:0},{height:h+'px',opacity:1}],{duration:260,easing:'cubic-bezier(.3,.8,.3,1)'}).onfinish=done;}
 else{const h=body.offsetHeight;body.style.overflow='hidden';body.animate([{height:h+'px',opacity:1},{height:'0px',opacity:0}],{duration:220,easing:'ease-in'}).onfinish=()=>{d.open=false;done();};}});
